import numpy as np
x=open('answer.xyz').readlines()[2:]
s=[]; p=[]
for l in x:
 a=l.split(); s.append(a[0]); p.append([float(z) for z in a[1:]])
p=np.array(p); rh=s.index('Rh'); print('Natoms',len(s),'Rh idx',rh)
# ligand heavy and Cp ranges from log estimate: extract index atom symbols indices
for j,a in enumerate(s):
 if j in [0,3,5,54,55,56,57,58,59,60]: print(j,a,p[j])
# closest pairs non hydrogen across atoms excluding Rh
pairs=[]
for i in range(len(s)):
 for j in range(i+1,len(s)):
  if s[i] in ('H','Rh') or s[j] in ('H','Rh'):continue
  # exclude bonds guesses dist <1.8 not useful
  d=np.linalg.norm(p[i]-p[j])
  if d<1.5: pairs.append((d,i,s[i],j,s[j]))
print('close heavy pairs',sorted(pairs)[:25])
